INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist es wahr, dass ein Virenscanner allein einen Client vollständig schützt?', 2, '[{"text": "Nein", "correct": true, "because": "Mehrschichtige Maßnahmen nötig"}, {"text": "Ja", "correct": false, "because": "Nicht gegen alle Bedrohungen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technologie schützt Daten auf einem Laptop bei Diebstahl?', 3, '[{"text": "Festplattenverschlüsselung", "correct": true, "because": "Verhindert Fremdzugriff"}, {"text": "Firewall", "correct": false, "because": "Schützt Netzwerk"}, {"text": "Antivirus", "correct": false, "because": "Für Malware"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen sichern einen Client effektiv?', 5, '[{"text": "Regelmäßige Updates", "correct": true, "because": "Schließen Sicherheitslücken"}, {"text": "Firewall", "correct": true, "because": "Blockiert Angriffe"}, {"text": "Bunte Icons", "correct": false, "because": "Kein Sicherheitsfaktor"}, {"text": "Hohe Auflösung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Zwei-Faktor-Authentifizierung erhöht Sicherheit. b) Sie ersetzt Antivirensoftware.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, ergänzt nur"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Absicherung eines Endgeräts?', 4, '[{"text": "Patch-Management", "correct": false, "because": "Schließt Lücken"}, {"text": "Antivirus-Software", "correct": false, "because": "Schützt vor Malware"}, {"text": "Bildschirmdesign", "correct": true, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob automatische Updates ausreichend sind?', 2, '[{"text": "Nein", "correct": true, "because": "Weitere Maßnahmen nötig"}, {"text": "Ja", "correct": false, "because": "Nicht allein ausreichend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahme verhindert Phishing-Angriffe am besten?', 4, '[{"text": "Schulung der Nutzer", "correct": true, "because": "Erhöht Awareness"}, {"text": "Schnelle CPU", "correct": false, "because": "Kein Schutzfaktor"}, {"text": "Hohe Auflösung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Firewalls alle Bedrohungen stoppen. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Nur ein Teil der Lösung"}, {"text": "Ja", "correct": false, "because": "Begrenzt auf Netzwerk"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Schützt ein Passwort-Manager vor Malware?', 2, '[{"text": "Nein", "correct": true, "because": "Nur für Zugangsdaten"}, {"text": "Ja", "correct": false, "because": "Kein Malwareschutz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technologien erhöhen die Client-Sicherheit?', 5, '[{"text": "Antivirus-Software", "correct": true, "because": "Erkennt Malware"}, {"text": "VPN", "correct": true, "because": "Sichert Verbindungen"}, {"text": "Grafikkarte", "correct": false, "because": "Kein Sicherheitsfaktor"}, {"text": "Bildschirmschoner", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Absicherung eines mobilen Clients?', 4, '[{"text": "Festplattenverschlüsselung", "correct": true, "because": "Schützt bei Verlust"}, {"text": "Hohe Akkulaufzeit", "correct": false, "because": "Sekundär"}, {"text": "Leichtes Gewicht", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Backups schützen vor Ransomware. b) Sie verhindern Angriffe.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, nur Wiederherstellung"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Client-Sicherheit?', 3, '[{"text": "Firewall", "correct": false, "because": "Blockiert Netzwerkangriffe"}, {"text": "Updates", "correct": false, "because": "Schließen Lücken"}, {"text": "Hintergrundbild", "correct": true, "because": "Kein Sicherheitsfaktor"}]'),
